from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether

OUT='output/pdf/TalentLens_TDD.pdf'
import os
os.makedirs('output/pdf',exist_ok=True)
ink=colors.HexColor('#202520'); green=colors.HexColor('#48624c'); muted=colors.HexColor('#747970'); pale=colors.HexColor('#f1f4ef'); line=colors.HexColor('#e2e6df')
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='CoverTitle',parent=styles['Title'],fontName='Helvetica-Bold',fontSize=27,leading=32,textColor=ink,alignment=TA_LEFT,spaceAfter=10))
styles.add(ParagraphStyle(name='Deck',parent=styles['Normal'],fontSize=11,leading=17,textColor=muted,spaceAfter=16))
styles.add(ParagraphStyle(name='H1x',parent=styles['Heading1'],fontName='Helvetica-Bold',fontSize=16,leading=20,textColor=ink,spaceBefore=9,spaceAfter=8,keepWithNext=True))
styles.add(ParagraphStyle(name='H2x',parent=styles['Heading2'],fontName='Helvetica-Bold',fontSize=10.5,leading=14,textColor=green,spaceBefore=7,spaceAfter=4,keepWithNext=True))
styles.add(ParagraphStyle(name='Bodyx',parent=styles['BodyText'],fontSize=8.6,leading=13,textColor=ink,spaceAfter=6))
styles.add(ParagraphStyle(name='Smallx',parent=styles['BodyText'],fontSize=7.5,leading=10.5,textColor=muted,spaceAfter=4))
styles.add(ParagraphStyle(name='Callout',parent=styles['BodyText'],fontSize=9,leading=14,textColor=ink,backColor=pale,borderColor=line,borderWidth=.5,borderPadding=9,spaceBefore=4,spaceAfter=9))
styles.add(ParagraphStyle(name='Cell',parent=styles['BodyText'],fontSize=7.4,leading=10,textColor=ink))
styles.add(ParagraphStyle(name='CellHead',parent=styles['BodyText'],fontName='Helvetica-Bold',fontSize=7.4,leading=10,textColor=colors.white))
P=lambda t,s='Bodyx':Paragraph(t,styles[s])
story=[]
story += [P('TECHNICAL DESIGN · 2026','Smallx'),P('TalentLens technical design','CoverTitle'),P('An evidence-led recruiting workspace for Company A. This document describes the core product slice, its data and scoring choices, and the safeguards and limits a reviewer should know.','Deck')]
story += [P('<b>GitHub project URL:</b> Not published from this workspace; no GitHub remote or publishing credentials were available at build time.','Callout'),P('<b>Live app:</b> Not deployed.','Smallx'),Spacer(1,5*mm)]
story += [P('Product and scope','H1x'),P('Recruiters edit a requisition scorecard, upload a batch of CVs, review ranked profiles with evidence, submit candidates, and follow progress. A client hiring manager sees masked profiles and can shortlist, reject with a reason, or propose an interview time. The delivery head can inspect a candidate activity log. The prototype focuses on the core slice; it does not connect to job boards, email, telephony, payments, or production identity providers.')]
story += [P('Architecture','H1x'),P('React with Vite provides the responsive single-page interface. Node.js and Express provide the API. PostgreSQL stores candidates, requisitions, submissions, and audit events. Multer bounds upload count and file size; pdf-parse reads selectable PDF text and Mammoth extracts DOCX text. Parsed data is persisted as a profile; the original file is not retained. Vite proxies /api requests to Express during local development.')]
story += [P('Architecture choices','H2x'),P('<b>React + Vite:</b> small interactive recruiter and client experiences with a fast local build. <b>Express:</b> direct route and role middleware for the prototype. <b>PostgreSQL:</b> relational requisition, candidate, submission, and audit records with foreign keys and unique hashes. <b>In-memory sessions:</b> adequate only for a local reviewer demo; production requires a durable session store.')]
story += [PageBreak(),P('Assumptions','H1x')]
assumptions=['Sample candidates are assumed to have consented to hiring use; new uploads require recruiter confirmation.','The first client identity is Northstar Bank; the demo client role is scoped to that client. Production must use authenticated tenant membership.','Seed profile fields are demonstration data, not real candidate records.','CVs are selectable-text PDFs or DOCX files; scanned-image OCR, encrypted PDFs, and language detection are outside this build.','Interview proposals are suggestions for recruiter coordination; no calendar invite or external message is sent.','The weighted score is an interpretable baseline, not a trained or generative model. Weights are fixed at 65% skills, 25% experience, and 10% notice.','The example JD does not state a CTC range, so the editable scorecard field is left blank.']
for i,a in enumerate(assumptions,1): story.append(P(f'<b>Assumption {i}.</b> {a}'))
story += [PageBreak(),P('Data model','H1x')]
data=[['Entity','Purpose','Key fields'],['jobs','Requisition and editable scorecard','Client, title, location, experience range, skills, maximum notice, CTC range'],['candidates','Parsed profile and consent state','ID, role, experience, skills, notice, summary, parsed CV text, consent, stage, content hash'],['submissions','Candidate shared for a requisition','Job, candidate, status, rejection reason, interview slot'],['audit','Candidate activity history','Actor, action, candidate ID, timestamp']]
t=Table([[P(c,'CellHead' if ri==0 else 'Cell') for c in row] for ri,row in enumerate(data)],colWidths=[27*mm,45*mm,104*mm],repeatRows=1)
t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),ink),('TEXTCOLOR',(0,0),(-1,0),colors.white),('BACKGROUND',(0,1),(-1,-1),colors.white),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,pale]),('GRID',(0,0),(-1,-1),.4,line),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]));story += [t,Spacer(1,4*mm),P('Candidate content hash is unique for duplicate detection. Candidate deletion cascades to submissions, then records a deletion event without retaining profile contents.','Callout')]
story += [P('Main flows','H1x')]
flows=[('1. Role entry','The demo entry screen establishes recruiter or client role in a session. Route middleware checks role for restricted API endpoints.'),('2. Scorecard','Recruiter reviews seeded JD fields and can edit title, skills, experience range, maximum notice, and CTC range. CTC is blank because the sample JD provides no value. API validation rejects empty or out-of-range values.'),('3. Bulk upload','Recruiter confirms consent and selects up to 500 PDF/DOCX files. Files are parsed in memory, duplicate hashes skipped, labelled fields extracted. Unsupported or unreadable files count as skipped.'),('4. Ranking and review','Candidates sort by score. Opening the evidence panel records a view event; the submit action appears after the recruiter opens the parsed CV text. Low-scoring candidates remain searchable.'),('5. Client review','Client sees only submitted Northstar Bank profiles, with contact/name masked. It can shortlist, reject with a reason, or propose date and time. Feedback is checked against the client scope.'),('6. Pipeline and audit','Recruiter follows six stages, reviews access/decision events, or deletes a profile on request.')]
for h,b in flows: story.append(KeepTogether([P(h,'H2x'),P(b)]))
story += [PageBreak(),P('AI and decision safeguards','H1x'),P('The matching logic is a deterministic scoring baseline. Required skill tokens contribute up to 65 points; experience in the job range contributes 25; notice within the JD limit contributes 10. Each result contains evidence for skills, experience, and notice. The ranked list displays source text and criterion detail with the score. This predictable approach is easy to inspect, but can miss synonyms and context; it is a prioritization aid.')]
story += [P('Names, gender, age, photo, and marital status are not scoring inputs. Client cards omit candidate names. A score never rejects a candidate, profiles remain searchable, and a recruiter opens the parsed CV text before submission. Weekly rank-versus-recruiter-choice comparison is not automated; score snapshots are not persisted yet.','Callout')]
story += [P('UI and design','H1x'),P('A restrained white, charcoal, and muted-green palette, compact type, and generous spacing keep attention on role fit and next actions. The desktop recruiter view uses a fixed sidebar. Overview prioritizes workload and requisitions; the ranked list makes score, notice, evidence, and action scannable. Evidence expands inline to preserve list context. The client portal uses masked candidate labels, direct actions, and single-column cards on phones. Empty states, error toasts, upload feedback, and mobile navigation are included.')]
story += [P('Security, privacy, and limits','H1x'),P('Routes validate role and important inputs. Uploads are limited to 8 MB per file, 500 files per request, and PDF/DOCX. Session cookies are HTTP-only and same-site; secure cookies activate in production. Candidate views, submissions, client decisions, and deletion events are logged. The demo does not claim DPDP Act compliance: it lacks a complete consent ledger, retention schedule, encryption-at-rest controls, production identity, durable session storage, rate limiting, and deletion verification. These are prerequisites before real candidate data is used.')]
story += [P('Testing','H1x'),P('Node built-in tests cover the exact-match score, missing-skill and low-score behavior, and skill weighting. The deployment guide provides commands for API tests and the production web build. Reviewer checks should include role boundaries, scorecard validation, upload limits and duplicates, feedback validation, and phone-width layouts.')]
story += [P('Cut and next steps','H1x'),P('This build cuts JD email intake, job-board sourcing, scanned-CV OCR, trained semantic ranking, calendar integration, recruiter/client messaging, production user administration, and automated weekly fairness comparisons. Next: OCR with confidence markers, consent and retention workflows, persistent sessions and migrations, tenant memberships, a reviewed synonym layer, decision-quality measurement, and accessibility review with recruiter and client feedback.')]

def footer(canvas,doc):
 canvas.saveState();w,h=A4;canvas.setStrokeColor(line);canvas.line(19*mm,15*mm,w-19*mm,15*mm);canvas.setFont('Helvetica',7);canvas.setFillColor(muted);canvas.drawString(19*mm,10*mm,'TALENTLENS  /  TECHNICAL DESIGN');canvas.drawRightString(w-19*mm,10*mm,f'{doc.page}');canvas.restoreState()
doc=SimpleDocTemplate(OUT,pagesize=A4,rightMargin=19*mm,leftMargin=19*mm,topMargin=17*mm,bottomMargin=21*mm,title='TalentLens technical design',author='Company A product prototype')
doc.build(story,onFirstPage=footer,onLaterPages=footer)
print(OUT)
